const http = require('http');
const fs = require('fs');
const path = require('path');
const ROOT = process.argv[2] || process.cwd();
const server = http.createServer((req, res) => {
  const urlPath = decodeURIComponent(new URL(req.url, 'http://x').pathname);
  const safe = path.normalize(path.join(ROOT, urlPath)).startsWith(path.normalize(ROOT));
  if (!safe) { res.writeHead(403).end('forbidden'); return; }
  fs.readFile(path.join(ROOT, urlPath), (err, data) => {
    if (err) { res.writeHead(404).end('not found'); return; }
    res.writeHead(200).end(data);
  });
});
server.listen(8080, () => console.log('serving ' + ROOT + ' on :8080'));

