const http = require('http');
const fs = require('fs');
const DB = 'messages.json';
if (!fs.existsSync(DB)) fs.writeFileSync(DB, '[]');
const server = http.createServer((req, res) => {
  if (req.method !== 'POST' || req.url !== '/contact') {
    res.writeHead(404).end('not found'); return;
  }
  let body = '';
  req.on('data', (c) => (body += c));
  req.on('end', () => {
    let m;
    try { m = JSON.parse(body); } catch { res.writeHead(400).end('bad json'); return; }
    if (!/\S+@\S+\.\S+/.test(m.email || '')) { res.writeHead(400).end('bad email'); return; }
    const all = JSON.parse(fs.readFileSync(DB, 'utf-8'));
    all.push({ email: m.email, message: String(m.message || ''), at: Date.now() });
    fs.writeFileSync(DB, JSON.stringify(all));
    res.writeHead(201).end('ok');
  });
});
server.listen(8080);

