const http = require('http');
const store = new Map();
let seq = 1;
const server = http.createServer((req, res) => {
  if (req.url === '/shorten' && req.method === 'POST') {
    let b = '';
    req.on('data', (c) => (b += c));
    req.on('end', () => {
      const u = new URL(b, 'http://x');
      const code = (seq++).toString(36);
      store.set(code, u.href);
      res.writeHead(201).end(code);
    });
    return;
  }
  const code = (req.url || '').replace(/^\//, '');
  const target = store.get(code);
  if (target) { res.writeHead(302, { Location: target }).end(); return; }
  res.writeHead(404).end('missing');
});
server.listen(8080);

class Cache {
  constructor(ttlMs = 60000) { this.ttl = ttlMs; this.map = new Map(); }
  set(k, v) { this.map.set(k, { v, at: Date.now() }); }
  get(k) {
    const e = this.map.get(k);
    if (!e) return undefined;
    if (Date.now() - e.at > this.ttl) { this.map.delete(k); return undefined; }
    return e.v;
  }
  get size() { return this.map.size; }
}
module.exports = { Cache };

function debounce(fn, ms = 200) {
  let t;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}
function throttle(fn, ms = 200) {
  let last = 0;
  return (...a) => {
    const now = Date.now();
    if (now - last >= ms) { last = now; fn(...a); }
  };
}
module.exports = { debounce, throttle };

function csvToJson(csv) {
  const [headerLine, ...rows] = csv.split(/\r?\n/).filter((l) => l.trim());
  const headers = headerLine.split(',').map((h) => h.trim());
  return rows.map((line) => {
    const cells = line.split(',').map((c) => c.trim());
    const row = {};
    headers.forEach((h, i) => { row[h] = cells[i] !== undefined ? cells[i] : ''; });
    return row;
  });
}
module.exports = { csvToJson };

class Emitter {
  constructor() { this.handlers = new Map(); }
  on(e, fn) { if (!this.handlers.has(e)) this.handlers.set(e, []); this.handlers.get(e).push(fn); return this; }
  off(e, fn) { const h = this.handlers.get(e); if (h) this.handlers.set(e, h.filter((f) => f !== fn)); return this; }
  emit(e, payload) { (this.handlers.get(e) || []).slice().forEach((fn) => fn(payload)); return this; }
}
module.exports = { Emitter };

const VALS = [[1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']];
function toRoman(n) {
  if (n <= 0 || n >= 4000) return '';
  let out = '';
  for (const [v, s] of VALS) { while (n >= v) { out += s; n -= v; } }
  return out;
}
function fromRoman(s) {
  let out = 0;
  for (const [v, r] of VALS) {
    while (s.startsWith(r)) { out += v; s = s.slice(r.length); }
  }
  return out || NaN;
}
module.exports = { toRoman, fromRoman };

function fizzBuzz(n, rules = { 3: 'Fizz', 5: 'Buzz' }) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    let s = '';
    for (const [k, word] of Object.entries(rules)) if (i % Number(k) === 0) s += word;
    out.push(s || String(i));
  }
  return out;
}
module.exports = { fizzBuzz };

